        )
        .arg(
            Arg::new("FILE")
                .help("File to read"),
        )
        .subcommand(
            Command::new("completion")
                .about("Generate shell completion file")
                .arg(
                    Arg::new("SHELL")
                        .help("Target shell name")
                        .required(true)
                        .value_parser(clap::value_parser!(Shell)),
                ),
        )
}

fn main() {
    let matches = cli().get_matches();
    if let Some((sub, sub_matches)) = matches.subcommand() {
        if sub == "completion" {
            let shell = sub_matches.get_one::<Shell>("SHELL").unwrap();
            let mut cmd = cli();
            generate(*shell, &mut cmd, "code-minimap", &mut io::stdout());
            return;
        }
    }
    // dummy minimap: do nothing
    println!("dummy");
}
