import subprocess

def run_orig(args, inp=None):
    return subprocess.run(["./executable"]+args, input=inp, capture_output=True)

def run_new(args, inp=None):
    return subprocess.run(["/tmp/claptest/target/debug/claptest"]+args, input=inp, capture_output=True)

# Test multiple files
for a in [["file1","file2"], [["README.md","LICENSE-MIT"]], ["--","file1","file2"], ["-H","1.0","file1","file2"]]:
    # flatten
    if isinstance(a[0], list):
        a=a[0]
    p1 = run_orig(a)
    print(f"ORIG {a} exit={p1.returncode} stdout={repr(p1.stdout[:200])} stderr={repr(p1.stderr[:500])}")

# Test with new (dummy minimap will just print dummy, but error cases should match)
for a in [["file1","file2"], ["README.md","LICENSE-MIT"], ["--","file1","file2"]]:
    p2 = run_new(a)
    print(f"NEW {a} exit={p2.returncode} stdout={repr(p2.stdout[:200])} stderr={repr(p2.stderr[:500])}")

# Test padding large error
for val in ["9999999999999999999999","18446744073709551616"]:
    p1 = run_orig(["--padding",val], b"a\n")
    p2 = run_new(["--padding",val], b"a\n")
