        inp=b"".join(lines)
        p = run([f"--vertical-scale={v_str}"], inp)
        out = p.stdout.decode()
        braille_lines = out.splitlines()
        filled=None
        for br_idx, br in enumerate(braille_lines):
            if not br:
                continue
            c=br[0]
            vbits=ord(c)-0x2800
            bits=[1 if vbits&1 else 0, 1 if vbits&2 else 0, 1 if vbits&4 else 0, 1 if vbits&64 else 0]
            for r,b in enumerate(bits):
                if b:
                    filled=br_idx*4+r
                    break
            if filled is not None:
                break
        res.append(filled)
    return res

