use std::fs::File;
use std::io::{self, Read, Write};
use std::path::PathBuf;
use std::process;

const BASH_COMPLETION: &str = include_str!("../completions/bash.txt");
const ELVISH_COMPLETION: &str = include_str!("../completions/elvish.txt");
const FISH_COMPLETION: &str = include_str!("../completions/fish.txt");
const POWERSHELL_COMPLETION: &str = include_str!("../completions/powershell.txt");
const ZSH_COMPLETION: &str = include_str!("../completions/zsh.txt");

fn cli() -> Command {
    Command::new("code-minimap")
        .version("0.6.8")
        .about("A high performance code minimap generator")
        .next_line_help(true)
        .disable_version_flag(true)
        .arg(
            Arg::new("HSCALE")
                .short('H')
                .long("horizontal-scale")
                .value_name("HSCALE")
                .help("Specify horizontal scale factor")
                .default_value("1.0")
                .value_parser(clap::value_parser!(f64)),
        )
        .arg(
            Arg::new("VSCALE")
                .short('V')
                .long("vertical-scale")
                .value_name("VSCALE")
                .help("Specify vertical scale factor")
                .default_value("1.0")
                .value_parser(clap::value_parser!(f64)),
        )
        .arg(
            Arg::new("PADDING")
                .long("padding")
                .value_name("PADDING")
                .help("Specify padding width")
                .value_parser(clap::value_parser!(u64)),
        )
        .arg(
            Arg::new("ENCODING")
                .long("encoding")
                .value_name("ENCODING")
                .help("Specify input encoding")
                .default_value("utf8-lossy")
                .value_parser(["utf8-lossy", "utf8"]),
        )
        .arg(
            Arg::new("version")
                .long("version")
                .help("Print version")
                .action(ArgAction::Version),
        )
