                .about("Generate shell completion file")
                .arg(
                    Arg::new("SHELL")
                        .help("Target shell name")
                        .required(true)
                        .value_parser(clap::value_parser!(clap_complete::Shell)),
                ),
        )
}

fn main() {
    let matches = cli().get_matches();
    if let Some((sub, sub_matches)) = matches.subcommand() {
        if sub == "completion" {
            let shell = sub_matches.get_one::<clap_complete::Shell>("SHELL").unwrap();
            let data: &str = match shell {
                clap_complete::Shell::Bash => BASH_COMPLETION,
                clap_complete::Shell::Elvish => ELVISH_COMPLETION,
                clap_complete::Shell::Fish => FISH_COMPLETION,
                clap_complete::Shell::PowerShell => POWERSHELL_COMPLETION,
                clap_complete::Shell::Zsh => ZSH_COMPLETION,
                _ => BASH_COMPLETION,
            };
            let stdout = io::stdout();
            let mut out = stdout.lock();
            // Ignore broken pipe, exit 0
            let _ = out.write_all(data.as_bytes());
            let _ = out.flush();
            return;
        }
    }

    let hscale = *matches.get_one::<f64>("HSCALE").unwrap();
    let vscale = *matches.get_one::<f64>("VSCALE").unwrap();
    let padding = matches.get_one::<u64>("PADDING").copied();
    let encoding = matches.get_one::<String>("ENCODING").unwrap().as_str();
    let file = matches.get_one::<PathBuf>("FILE");

    // Read input
    let content: String = if let Some(path) = file {
        // Open file
        let mut f = match File::open(path) {
            Ok(f) => f,
            Err(e) => {
                eprintln!("code-minimap: {}", e);
                process::exit(1);
            }
        };
        if encoding == "utf8" {
            let mut s = String::new();
            match f.read_to_string(&mut s) {
                Ok(_) => s,
                Err(e) => {
                    eprintln!("code-minimap: {}", e);
                    process::exit(1);
                }
            }
        } else {
            // utf8-lossy
            let mut buf = Vec::new();
            if let Err(e) = f.read_to_end(&mut buf) {
                eprintln!("code-minimap: {}", e);
                process::exit(1);
            }
            String::from_utf8_lossy(&buf).into_owned()
        }
    } else {
        // stdin
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        if encoding == "utf8" {
            let mut s = String::new();
            match handle.read_to_string(&mut s) {
                Ok(_) => s,
                Err(e) => {
                    eprintln!("code-minimap: {}", e);
                    process::exit(1);
                }
            }
        } else {
            let mut buf = Vec::new();
            if let Err(e) = handle.read_to_end(&mut buf) {
                eprintln!("code-minimap: {}", e);
                process::exit(1);
            }
            String::from_utf8_lossy(&buf).into_owned()
        }
    };

    // Process lines
    let lines: Vec<&str> = content.lines().collect();
    // Compute blocks per line: Option<(indent, end)>
    let mut blocks: Vec<Option<(usize, usize)>> = Vec::with_capacity(lines.len());
    for line in &lines {
        let mut first: Option<usize> = None;
        let mut last: Option<usize> = None;
        for (idx, ch) in line.char_indices() {
            if !ch.is_whitespace() {
                if first.is_none() {
                    first = Some(idx);
                }
                last = Some(idx);
            }
        }
        match (first, last) {
            (Some(f), Some(l)) => blocks.push(Some((f, l + 1))),
            _ => blocks.push(None),
        }
    }

    // V grouping: compute key per line, group consecutive same keys
    // groups: Vec<Option<(min_indent, max_end)>>
    let mut groups: Vec<Option<(usize, usize)>> = Vec::new();
    if !lines.is_empty() {
        let mut current_key: Option<usize> = None;
        let mut cur_min: Option<usize> = None;
        let mut cur_max: Option<usize> = None;
        for (i, blk) in blocks.iter().enumerate() {
            let key = (i as f64 * vscale) as usize;
            if current_key != Some(key) {
                if current_key.is_some() {
                    // push previous group
                    match (cur_min, cur_max) {
                        (Some(mn), Some(mx)) => groups.push(Some((mn, mx))),
                        _ => groups.push(None),
                    }
                }
                current_key = Some(key);
                cur_min = None;
                cur_max = None;
            }
            if let Some((indent, end)) = blk {
                cur_min = Some(cur_min.map_or(*indent, |m| m.min(*indent)));
                cur_max = Some(cur_max.map_or(*end, |m| m.max(*end)));
            }
        }
        // push last
        match (cur_min, cur_max) {
            (Some(mn), Some(mx)) => groups.push(Some((mn, mx))),
            _ => groups.push(None),
        }
    }

    let num_output_rows = groups.len();
    let num_braille_rows = (num_output_rows + 3) / 4;

    // Padding panic emulation: if padding > 65535 and num_braille_rows > 0, panic
    if let Some(pad) = padding {
        if pad > 65535 && num_braille_rows > 0 {
            let pid = process::id();
            eprint!("\nthread 'main' ({} ) panicked at /workspace/src/core.rs:96:26:\nFormatting argument out of range\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", pid);
            // Note: need exact format: "thread 'main' (PID) panicked at ..."
            // Our format has extra space? Let's fix: should be "({})" not "({} )"
            process::exit(101);
        }
    }

    // If no rows, output nothing (even with padding, no rows => no output)
    if num_braille_rows == 0 {
        return;
    }

    // Prepare scaled blocks per output row: Vec<(scaled_indent, scaled_end, has_fill)>
    // For empty groups: scaled_indent=0, scaled_end=(1.0*hscale) as usize, has_fill=false
    // For Some: scaled as above, has_fill = scaled_indent < scaled_end
    let mut scaled: Vec<(usize, usize, bool)> = Vec::with_capacity(num_output_rows);
    for g in &groups {
        match g {
            None => {
                let se = (1.0f64 * hscale) as usize;
                scaled.push((0, se, false));
            }
            Some((indent, end)) => {
                let si = (*indent as f64 * hscale) as usize;
                let se = (*end as f64 * hscale) as usize;
                let has = si < se;
                scaled.push((si, se, has));
            }
        }
    }

    let stdout = io::stdout();
    let mut out = stdout.lock();

    for b in 0..num_braille_rows {
        let start = b * 4;
        let end = std::cmp::min(start + 4, num_output_rows);
        // width = max scaled_end in this braille row
        let mut width: usize = 0;
        for idx in start..end {
            let se = scaled[idx].1;
            if se > width {
                width = se;
            }
        }
        let num_cells = (width + 1) / 2;
        // Allocate braille bits (this may panic with capacity overflow for huge width, matching original)
        let mut bits = vec![0u8; num_cells];
        // Fill pixels
        for r in 0..(end - start) {
            let idx = start + r;
            let (si, se, has) = scaled[idx];
            if !has {
                continue;
            }
            // For c in si..se, set pixel (r,c)
            // Optimize: iterate c
            for c in si..se {
                let cell = c / 2;
                let is_right = (c % 2) == 1;
                let bit: u8 = match (r, is_right) {
                    (0, false) => 0x01,
                    (0, true) => 0x08,
                    (1, false) => 0x02,
                    (1, true) => 0x10,
                    (2, false) => 0x04,
                    (2, true) => 0x20,
                    (3, false) => 0x40,
                    (3, true) => 0x80,
                    _ => 0,
                };
                // cell < num_cells guaranteed since c < width
                bits[cell] |= bit;
            }
        }
        // Convert to string
        let mut s = String::with_capacity(num_cells * 3);
        for bval in bits {
            let ch = char::from_u32(0x2800 + bval as u32).unwrap();
            s.push(ch);
        }
        // Apply padding
        let line_out: String = if let Some(pad) = padding {
            // pad <= 65535 here (larger already handled as panic)
            let pad_usize = pad as usize;
            if s.chars().count() >= pad_usize {
                s
            } else {
                // Pad with spaces to pad_usize chars
                // Use format! to match original's formatting? Original uses format!("{:<pad$}", s)
                // For braille (each 1 char), this pads with spaces. Good.
                // We can do manually to avoid panic for large pad (already handled)
                let mut padded = s;
                let need = pad_usize - padded.chars().count();
                for _ in 0..need {
                    padded.push(' ');
                }
                padded
            }
        } else {
            s
        };
        // Write line (ignore broken pipe)
        if writeln!(out, "{}", line_out).is_err() {
            // Broken pipe or other error: exit 0 silently (matching original)
            // Need to check if error is broken pipe? Original ignores all? We'll just exit 0.
            return;
        }
    }
    let _ = out.flush();
}
